from google import genai
from google.genai import types
client = genai.Client(api_key='[REDACTED]')
try:
    response = client.models.generate_content(
        model='gemini-2.5-flash-image',
        contents='Generate a simple blue square on white background',
        config=types.GenerateContentConfig(
            response_modalities=['IMAGE','TEXT'],
        )
    )
    for part in response.candidates[0].content.parts:
        if part.inline_data:
            print(f'Got image: {part.inline_data.mime_type}, {len(part.inline_data.data)} bytes')
        elif part.text:
            print(f'Got text: {part.text[:100]}')
except Exception as e:
    print(f'Error: {e}')
" 2>&1
